int unopt_char(char bit_position)
{
    switch (bit_position)
    {
        case (1 << 0):
            return 0;
        case (1 << 1):
            return 1;
        case (1 << 2):
            return 2;
        case (1 << 3):
            return 3;
        case (1 << 4):
            return 4;
        case (1 << 5):
            return 5;
        case (1 << 6):
            return 6;
        default:
            return 0;
    }
}

